  _closed(){if(this.readyState!==CLOSED){this.readyState=CLOSED;this.emit('close');}}
  _parse(data){this._buffer=Buffer.concat([this._buffer,data]);while(true){if(this._buffer.length<2)return;const b0=this._buffer[0],b1=this._buffer[1];const fin=!!(b0&128),opcode=b0&15;let len=b1&127,off=2;if(len===126){if(this._buffer.length<4)return;len=this._buffer.readUInt16BE(2);off=4}else if(len===127){if(this._buffer.length<10)return;const hi=this._buffer.readUInt32BE(2);const lo=this._buffer.readUInt32BE(6);if(hi>0x1fffff)return this.close(1009,'too large');len=hi*4294967296+lo;off=10}const masked=!!(b1&128);if(masked)off+=4;if(this._buffer.length<off+len)return;if(len>16*1024*1024)return this.close(1009,'too large');let payload=this._buffer.subarray(off,off+len);if(masked){const key=this._buffer.subarray(off-4,off);payload=Buffer.from(payload);for(let i=0;i<payload.length;i++)payload[i]^=key[i&3]}this._buffer=this._buffer.subarray(off+len);if(!fin)continue;if(opcode===0x8){this.close(1000,'');continue}if(opcode===0x9){this._frame(0xA,payload);this.emit('ping',payload);continue}if(opcode===0xA){this.emit('pong',payload);continue}if(opcode===0x1||opcode===0x2){this.emit('message',payload)} }}
  _frame(op,payload){if(this.readyState!==OPEN)return false;payload=Buffer.isBuffer(payload)?payload:Buffer.from(payload);let h;if(payload.length<126)h=Buffer.from([0x80|op,payload.length]);else if(payload.length<=65535){h=Buffer.alloc(4);h[0]=0x80|op;h[1]=126;h.writeUInt16BE(payload.length,2)}else{h=Buffer.alloc(10);h[0]=0x80|op;h[1]=127;h.writeUInt32BE(Math.floor(payload.length/4294967296),2);h.writeUInt32BE(payload.length>>>0,6)}try{this._socket.write(Buffer.concat([h,payload]));return true}catch{return false}}
  send(data,cb){const ok=this._frame(1,Buffer.from(String(data)));if(cb)cb(ok?null:new Error('send failed'));return ok}
