  close(code=1000,reason=''){if(this.readyState===CLOSED)return;try{const body=Buffer.alloc(2+Buffer.byteLength(reason));body.writeUInt16BE(code,0);Buffer.from(reason).copy(body,2);this._frame(8,body)}catch{}try{this._socket.end()}catch{}this._closed();}
