WebSocket.OPEN=OPEN;WebSocket.CLOSED=CLOSED;
class Server extends EventEmitter{
 constructor(opts={}){super();this.clients=new Set();this._server=opts.server;if(!this._server)throw new Error('ws-lite requires an existing HTTP server');this._server.on('upgrade',(req,socket)=>this._upgrade(req,socket));}
 _upgrade(req,socket){try{if(req.headers.upgrade?.toLowerCase()!=='websocket'){socket.destroy();return}const key=req.headers['sec-websocket-key'];if(!key){socket.destroy();return}const accept=crypto.createHash('sha1').update(key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+accept+'\r\n\r\n');const ws=new WebSocket(socket);this.clients.add(ws);ws.on('close',()=>this.clients.delete(ws));this.emit('connection',ws,req)}catch{try{socket.destroy()}catch{}}}
}
